	/**
		Returns a `GroupListViewItemState` representing a specific item.

		@since 1.3.0
	**/
	public function itemToItemState(item:Dynamic):GroupListViewItemState {
		if (item == null) {
			return null;
		}
		var itemState:GroupListViewItemState = null;
		var itemRenderer:DisplayObject = null;
		if ((item is String)) {
			itemRenderer = this.stringDataToItemRenderer.get(cast item);
		} else {
			itemRenderer = this.objectDataToItemRenderer.get(item);
		}
		if (itemRenderer != null) {
			itemState = this.itemRendererToItemState.get(itemRenderer);
		} else {
			var location = this._dataProvider.locationOf(item);
			if (location == null) {
				return null;
			}
			itemState = new GroupListViewItemState();
			var type = location.length == 1 ? HEADER : STANDARD;
			var layoutIndex = this.locationToDisplayIndex(location);
			this.populateCurrentItemState(item, type, location, layoutIndex, itemState, false);
		}
		return itemState;
	}

	override public function dispose():Void {
		this.refreshInactiveItemRenderers(this._defaultItemStorage, true);
		if (this._additionalItemStorage != null) {
			for (i in 0...this._additionalItemStorage.length) {
				var storage = this._additionalItemStorage[i];
				this.refreshInactiveItemRenderers(storage, true);
			}
		}
		this.refreshInactiveItemRenderers(this._defaultHeaderStorage, true);
		if (this._additionalHeaderStorage != null) {
			for (i in 0...this._additionalHeaderStorage.length) {
				var storage = this._additionalHeaderStorage[i];
				this.refreshInactiveItemRenderers(storage, true);
			}
		}
		// manually clear the selection so that removing the data provider
		// doesn't result in Event.CHANGE getting dispatched
		this._selectedItem = null;
		this._selectedLocation = null;
		this.dataProvider = null;
		super.dispose();
	}

