@:event(openfl.events.Event.TAB_CHILDREN_CHANGE)
@:event(openfl.events.Event.TAB_ENABLED_CHANGE)
@:event(openfl.events.Event.TAB_INDEX_CHANGE)
@:event(openfl.events.FocusEvent.FOCUS_IN)
