		var adjustedHorizontalGap = this._horizontalGap;
		var hasFlexHorizontalGap = this._horizontalGap == (1.0 / 0.0);
		if (hasFlexHorizontalGap) {
			adjustedHorizontalGap = this._minHorizontalGap;
		}

