			if (this._virtualCache != null) {
				var cacheItem = Std.downcast(this._virtualCache[i], VirtualCacheItem);
				if (cacheItem != null && (cacheItem.itemHeight == null || cacheItem.itemHeight != itemHeight)) {
					cacheItem.itemHeight = itemHeight;
