							for (j in 0...skippedMissingItems) {
								positionY += estimatedItemHeight + adjustedGap;
								if (startIndex == -1 && positionY >= scrollY) {
									startIndex = j;
								}
								if (startIndex != -1) {
									endIndex = j;
