			this._uiContext.removeEventListener(FeathersEvent.STATE_CHANGE, uiContext_stateChangeHandler);
			if ((this._uiContext is IToggle)) {
				this._uiContext.removeEventListener(Event.CHANGE, uiContextToggle_changeHandler);
			}
